INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ab381163-9191-407d-87e6-39352b13309a', '21feff02-016d-46e2-bb9d-c27495133b1b', '1. óra: Az év bevezetése, ismétlés, játékos bevezető', 'Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "75009fc2-da7a-4a73-8c1a-d5b28412dede", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "ac581ff8-43b7-4db6-9fc2-b738079b9d47", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "3761627a-ea2a-45c2-8349-8ca71cb958d5", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "e7fcfd66-8df6-487a-af50-0fa2b39a7a09", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "05458ade-95ec-480c-a4ea-6a2f2925e1b1", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "7acb4da1-305d-475a-a4c0-8da30dad6c4a", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "1c446a91-8911-4002-964f-f7926dba4673", "text": "Igaz", "isCorrect": true}, {"id": "386c75c6-add0-4397-9e01-6f72396c92c3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b5310ffb-b334-409a-9a75-a0bd358f3e02", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "1370a7a5-23fa-41d2-8db5-47debc732690", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "23f508f6-2fea-477d-831b-a9106ab8a50a", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "63ca7d63-f9f6-42b1-a26e-3f5b1221933d", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "b31017ec-dbc7-4d00-b4cc-c6cca0a81f69", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "a24703b5-818d-48fb-b847-f5481f53a2dc", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "a2506200-63b8-466d-b5d9-8fc02bd4ff07", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "be4dd829-a890-468a-b0bb-7ff70b3b7790", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "ea9c9673-f366-4971-99b9-0a5b9aa34f89", "text": "Igaz", "isCorrect": true}, {"id": "48100083-3f3a-491d-850d-bac79d086b56", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a17802f1-57c5-4313-b787-ba43e77834b6", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c8258162-c9fe-424c-a2a7-8d1a1d15e0c1', '21feff02-016d-46e2-bb9d-c27495133b1b', '2. óra: Játékok', 'Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "a74bf299-5400-4c3c-8d8c-c6a35029b1f7", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "5f7d51b6-64ce-4425-b6a9-29c782be2464", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "6f3f79bd-3bdf-4f3c-b953-5aba5b46e0cd", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "80c354f1-7353-44f4-aeea-5ef2061dc95f", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "1bec3a6d-ce73-4b45-9b7d-da4af8dc2810", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "8a072c71-c86d-4032-93aa-3b2e25c2f980", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "0e8df389-9f38-47d6-9b20-8c8ae4546200", "text": "Igaz", "isCorrect": true}, {"id": "7c2fab7d-8be8-4ac6-ab69-3dd717eb396c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "be9d68a5-5540-41b4-86c1-ec47826c93b2", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "6145efaa-7ba0-42d4-ba61-5c16e561e57e", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "0980b93f-5629-4f96-a330-71facc729c15", "text": "Sudoku", "isCorrect": true}, {"id": "f57acb93-068d-4711-8b75-dcdd790b59eb", "text": "Fócsoport", "isCorrect": false}, {"id": "a2df23ff-6375-4412-9fe2-f5930ea3dd5f", "text": "Futóverseny", "isCorrect": false}, {"id": "ff9f9c53-2e38-466b-918b-f1bb7313fd23", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "7dfca067-9784-46ef-b552-6899777dac57", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "582d4452-b063-4ae1-b03b-e83cfd0b52e3", "text": "Igaz", "isCorrect": true}, {"id": "dd6d6490-1dfc-4086-bde4-a49b0696fce7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5d7b39dc-2260-4942-8159-0aff5c1d612b", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "1102285b-b1cf-4e75-a620-e181d1ed4b8b", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "cc22f0c7-b87c-4718-9993-8942427814c8", "text": "Igaz", "isCorrect": true}, {"id": "9dfc876a-6b0f-4fc4-82fe-f23be58ae1a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7a636428-821e-48e3-b347-76eed62fb18f', '21feff02-016d-46e2-bb9d-c27495133b1b', '3. óra: Év eleji diagnosztikus felmérés', 'Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "d22eae82-336f-4945-b301-7310f792256d", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "303ab009-a49b-470b-a5ea-fe2766f476ec", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "f9a2d617-cc9c-4691-842b-47f01bbcb6ba", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "d3e4ad84-8b2d-437d-a1c7-492615f77724", "text": "2/4", "isCorrect": false}, {"id": "80527496-3b90-48b8-9f94-29c84901419a", "text": "4/8", "isCorrect": false}, {"id": "0c2fdd39-9fad-41d2-8540-c9da30c431b2", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "32095f92-98d6-42ab-9797-4bec1d03429f", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "f7b62260-b5f0-4cfa-81f5-4cbe2bf23623", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "cf8bf5b7-dd4d-4841-b7c4-9f03cbfcd419", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "c439bc63-1da9-41f6-af68-442ef6525186", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "757927e0-e4eb-4c14-83c8-975a95985430", "text": "Igaz", "isCorrect": true}, {"id": "6642e31c-c27d-4d7a-a7db-1bbc7882cb29", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b2dfd8c3-a5a6-4e17-b10b-7ce26da480e8", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "eb6b8df5-770e-4723-b75a-d8b6572ae652", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "06b3ba61-627f-4383-bdd6-e520c1806736", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "cbc99f66-33ed-4dbb-ae9a-7fef8ba888fd", "text": "Igaz", "isCorrect": true}, {"id": "96d5cb1a-91d0-49bc-91ec-4acac6a2d503", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "13cbf562-89b9-47cf-bc44-a401baa9159e", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('714794a5-a869-459a-bcb5-cf1773c937ef', '21feff02-016d-46e2-bb9d-c27495133b1b', '4. óra: Műveletek az egész számok körében', 'Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "8caddf2f-07da-4ff0-ac89-ef88ac887021", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "164da9cc-c834-45b6-845f-18aedfbc86e8", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "cabcd8cd-cba1-4cd0-ba16-b15e63b43796", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "047a9b9e-47e5-4e95-9d32-9e2258f9cd1f", "text": "Igaz", "isCorrect": true}, {"id": "b698649b-b951-4d13-877b-8b83019cd9ad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8803fd5d-f3a1-49a5-8372-40125cc98872", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "6e059ed3-ee76-472d-8e37-f2d6e4697cd0", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "a3938ddd-903c-4b2f-9a1a-e4a9f856ebf3", "text": "-8", "isCorrect": true}, {"id": "85ee0de3-4960-4311-a89a-d3cf0cc130b8", "text": "-15", "isCorrect": false}, {"id": "77a670e0-aac2-444e-9d99-210d08bd5853", "text": "Egyenlőek", "isCorrect": false}, {"id": "fedfc91a-7d12-4579-9357-0fb8184c78c3", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "7025f86a-04e3-4cac-8db8-499eb2a49f6e", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "5e919079-7ee5-4ca4-9a41-2e9e97e897ba", "text": "Igaz", "isCorrect": true}, {"id": "54c69340-834b-456e-8111-4c4472717e54", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "50790749-b7c2-47f4-a3c6-99ab9b6b8385", "text": "Mennyi (-10) + (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('925f2a85-72dd-4eb7-97f5-2e6e1f66c4a0', '21feff02-016d-46e2-bb9d-c27495133b1b', '5. óra: Az egész számok szorzása', 'Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9b4fc8aa-7c4c-4be7-941f-9f7bb717c1c2", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "fd85360c-ffcc-408c-8b23-9f9528f650a3", "text": "Pozitív (+)", "isCorrect": true}, {"id": "bd35c9dc-53b9-4d66-a8b6-aa3f0b0af32e", "text": "Negatív (-)", "isCorrect": false}, {"id": "ccef4b9e-c066-4582-b286-961d2ceb83b1", "text": "Mindig 0", "isCorrect": false}, {"id": "4e8c2779-4688-4648-8360-86468f9423c5", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "ce8ff95c-00dc-46c7-8f6b-091b45f69f1a", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "ac97a137-a7d1-42bc-810c-301f7140475a", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "0b92a7b9-dd73-46e5-8cfe-7914358f48a6", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "22828367-a602-4267-b2f4-768178e01f11", "text": "Igaz", "isCorrect": true}, {"id": "ba1c4220-310b-42e1-a204-9fc42b36132d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c921d158-9c86-4d15-9e39-b26b23009b25", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "35528599-d991-4026-be04-26841d7b307c", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "95233aa9-03aa-4ed5-b40f-fabbbb3a4493", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "e511f98f-1226-4ab6-960a-aa6fb287358c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e564ad18-9502-4ff0-a888-b57ea4570546", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8a6b9c33-9ab2-4ed8-917a-9d1ddc98d0be', '21feff02-016d-46e2-bb9d-c27495133b1b', '6. óra: Gyakorlóóra: az egész számok szorzása', 'Több tényező előjelének meghatározása, szorzások gyakorlása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "dec35c95-631f-4a6c-8d98-f465dced4a8d", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "1714982a-8ae4-4863-aad5-ee470f1c2e21", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "e070b11f-a9af-4517-af33-e180be2d6094", "text": "Pozitív", "isCorrect": true}, {"id": "ea62d2d4-4ed4-4c37-9296-abd6664dc975", "text": "Negatív", "isCorrect": false}, {"id": "841a98b3-fddf-4593-900b-00f34525be23", "text": "Nulla", "isCorrect": false}, {"id": "d0be8066-f81d-49b9-94eb-0a2c91dcc986", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "783a00d8-c132-4ff2-9ed7-b9770b1521ab", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "566fceb9-61b4-4cc7-bb8d-59b02b5b026e", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "0967e1da-5496-4f00-a31c-21643ccfc2ec", "text": "Igaz", "isCorrect": true}, {"id": "8d80b203-aa16-4234-b10f-549089c16d3e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8c9f6fa-71d2-41a5-ace8-e10e99e12ed2", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "2b8f1e46-01fe-47eb-a0e6-da1e1aee99c6", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "19988890-7432-42cb-93d7-e2ea96b5fa76", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "ca4491e3-28c6-4c7e-92f3-7291ffef4b75", "text": "Igaz", "isCorrect": true}, {"id": "f3f14464-b3ca-4a68-b004-dab377928089", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bf6ee4cf-5c60-4464-b8bf-c4b81d71197d', '21feff02-016d-46e2-bb9d-c27495133b1b', '7. óra: Az egész számok osztása', 'Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "3f81e830-45d3-419e-a2cd-ac58295e4c50", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "b82392a8-7247-4a7f-bd41-eaab5353e3b5", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "93e0cfc9-c1df-44cc-a95f-e3656779d411", "text": "Mindig negatív", "isCorrect": false}, {"id": "a0f09038-65cd-4d0a-a098-f1545e3c4362", "text": "Mindig pozitív", "isCorrect": false}, {"id": "6a8008a0-8051-4f80-a7b9-bab9f81179ce", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "ca0de4ba-9271-4b04-a84f-f76402f28fb4", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "0345688c-8a33-48c1-a5bc-1a3b8c36b597", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "e4a528f3-ba1c-42ed-94a6-52a709a6eb8d", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "8894f7c7-9db9-4680-b2b7-a2de465809c3", "text": "Igaz", "isCorrect": true}, {"id": "32537053-9557-432e-82a7-785554d7bec3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "658ef223-bdfa-4be4-8ac7-c98182bbbdfd", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "94623f3e-3bd6-480b-b6f7-2d1282e59f59", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "25c0f070-a549-4d90-ab3e-dfd2c8a36a78", "text": "Igaz", "isCorrect": true}, {"id": "69f90fa8-43bb-4899-86df-7b4a7fadc6b0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a24bc52-b43d-4ffd-82a9-19ddeb6d068d", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('05b047c9-6127-4a2a-9b46-45f0d00c6cbd', '21feff02-016d-46e2-bb9d-c27495133b1b', '8. óra: Az egész számok osztásának gyakorlása', 'Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "221ec72d-17db-468b-b0ee-e4c30dc0bb68", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "0095d8dc-04d1-4aa6-a882-1319de038914", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "0761ece0-d504-4236-ae3e-19d1acc331ee", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "3e9c79c2-f0a1-42aa-a02c-9bb392596b25", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "3167406d-892a-4d5f-9c07-a1c7123fecc5", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "9293be21-134a-4543-9e59-9b15f327557f", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "b1cbeb8d-755a-4c83-a4eb-b33bacb71631", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "49518322-8236-497b-9033-4f59d6f3d25c", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "b4184d9d-9c12-400d-812d-0549fb098279", "text": "Igaz", "isCorrect": true}, {"id": "e6520d05-d1f3-42d3-a943-a58461359d95", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1f81d981-30a8-4916-88ac-a1a371fc5333", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "5ab0d574-1413-4cdb-a37a-7a31e1f0dc59", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "aa210675-aa20-4d53-a2ba-9bc1af9e88fb", "text": "Igaz", "isCorrect": true}, {"id": "0e79e033-6ab8-47df-9174-826c561aaafb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1f76321-a21e-43df-99df-8e80bfcb8754", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d3fcad24-8a0d-4413-9b9b-fecb2fe663aa', '21feff02-016d-46e2-bb9d-c27495133b1b', '9. óra: Hány eset van? Számoljuk össze!', 'Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "a8488cbf-12a7-485b-9f53-bb569d7f83b2", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "e9b1ea94-4e42-4a60-8dd8-28e81cb987ee", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "c7c0447e-362a-4889-ba9c-76ab083dac0d", "text": "Szögmérőt", "isCorrect": false}, {"id": "61f1fde2-d1af-4f3c-8373-e4f03e86e1d9", "text": "Körzőt", "isCorrect": false}, {"id": "bbcf00d0-005b-4edd-85da-cbdd8bac4e3a", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "86d8d78b-b073-482b-bdf3-c1feca37674d", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "0c09f030-7ac9-4233-b3e8-ffb1ed1645ec", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "5a38de1c-ced4-492a-a3d2-2ccf4ebc916b", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "60f1c214-7d7a-4335-8438-6ac0e58fc491", "text": "Igaz", "isCorrect": true}, {"id": "fde8f338-2af1-4eba-88ad-a7680993233c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "600c4d21-54ee-4ff6-837e-5e7ff88c32f7", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "9c7fd3ee-e726-428a-a918-70d57b44cc29", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "b38e9fef-943c-4ee7-a389-e449bb5e2ffa", "text": "Igaz", "isCorrect": false}, {"id": "ba19d710-86f5-4563-ad36-d19dd35bedc6", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "88557b9c-a584-4314-960a-700e782a9bfc", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8cf0c908-f4f2-49cd-8f2a-ffafae6cf570', '21feff02-016d-46e2-bb9d-c27495133b1b', '10. óra: Gyakorlóóra. Hány eset van? Számoljuk össze!', 'Összeszámlálási feladatok gyakorlása fagráffal és táblázattal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "679c2dcd-7b80-4f4d-928d-a55effbddd48", "text": "Hány 2 jegyű páros szám képezhető az 1, 2, 3 számjegyekből (számjegyismétlés nélkül)?", "type": "multiple-choice", "options": [{"id": "12f9d298-b1ec-4b64-9d5d-a643b93af584", "text": "2 (12, 32)", "isCorrect": true}, {"id": "43be262a-19fe-4852-b846-dfc89ff91d20", "text": "3", "isCorrect": false}, {"id": "ca5c3be3-f231-42c0-922e-53457018f2a0", "text": "4", "isCorrect": false}, {"id": "1a684681-fffe-4c33-a5fe-0780623251ef", "text": "6", "isCorrect": false}], "timeLimit": 15}, {"id": "2882fa90-6f4a-42c9-be03-de94804c7fe6", "text": "Három barát köszöntésekor (mindenki mindenkivel kezet fog) hány kézfogás történik?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "11a543d7-53bd-4886-8ae6-6246cb5758a4", "text": "A fagráf ágai az egyes döntési lépéseket ábrázolják.", "type": "true-false", "options": [{"id": "26fc4051-8798-434d-9ba3-72844617c6b6", "text": "Igaz", "isCorrect": true}, {"id": "7f1da50d-8b42-4e26-b141-0dac34094dbe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "780bc250-c517-4aae-a6b2-047fab9ea051", "text": "Hány különböző sorrendben futhat be a célba 3 versenyző (A, B, C)? (3! = 3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4f8fff5b-1876-4a20-a0e3-a997ad223a64", "text": "Ha 4 csapat játszik körmérkőzést (mindenki mindenkivel egyszer), hány mérkőzést játszanak összesen?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "655dad45-5e17-4c3b-a38f-b691f7ae173d", "text": "Egy szabályos dobókocka eldobásakor 6-féle kimenetel lehetséges.", "type": "true-false", "options": [{"id": "e6d16b9c-17a7-4b52-8ff0-3c83d3ee4af8", "text": "Igaz", "isCorrect": true}, {"id": "bbce85e6-9849-4e54-83d9-954c404f8f42", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca6993e2-7375-4f62-b0c0-068c5e19af38", "text": "Hány kétjegyű szám képezhető a 0 és 5 számjegyekből (0 nem lehet az első számjegy)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;